def compute(vars):
    initial_equity = vars["Initial Equity"]
    final_equity = vars["Final Equity"]

    average_equity = (initial_equity + final_equity) / 2

    return {
        "value": average_equity,
        "trace": {
            "Initial Equity": initial_equity,
            "Final Equity": final_equity,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": None
            }
        }
    }
